/**
 * `/team` final-message assembly.
 *
 * The closing contract and the per-proposal adoption status are generated by
 * code from structured tracking; the synthesis sub-call never authors them.
 * When its text disagrees with the tracking, the tracking wins — an invalid
 * recommendation is dropped here with an explicit note.
 */
import { stripInlineMarkdown } from "@oh-my-pi/pi-tui/overlays/plan-toc";
import { normalizeHtmlEntitiesForTerminal } from "@oh-my-pi/pi-tui/utils/html-entities";
import { Lexer } from "@oh-my-pi/pi-utils/marked";
import type { TeamAlignmentOutput, TeamProposalRecord, TeamSynthesisOutput } from "./types";

/** Fixed closing contract, verbatim from docs-zh-CN/requirements/team.md §2.7. */
export const TEAM_CLOSING_CONTRACT = [
	'> 选择方案请直接回复（如"选择方案 A"）。选择仅确认该方案、其验收标准与执行前检查，不触发实施；如需修改代码，请另行明确要求。若存在影响选择的"需求理解差异"，请先回答该差异并带答案重跑 `/team`，不要在不同前提的方案间盲选。',
].join("\n");

export interface AssembleReportArgs {
	alignment: TeamAlignmentOutput;
	synthesis: TeamSynthesisOutput;
	proposals: readonly TeamProposalRecord[];
	/** Notes about incomplete participation, wiki gaps, etc. */
	participationNotes: readonly string[];
}

export interface AssembleReportResult {
	ok: true;
	markdown: string;
	/** True when structured tracking overrode the synthesis recommendation. */
	droppedRecommendation: boolean;
}

export interface AssembleReportConflict {
	ok: false;
	error: string;
}

function proposalLabel(record: TeamProposalRecord): string {
	return `方案 ${record.label}`;
}

/**
 * Model-authored text lands inside the mechanically generated status table
 * and notice blockquotes. Raw pipes would forge or break table cells and raw
 * newlines would break rows/quote lines, so both are neutralized before the
 * generated structure is assembled.
 */
function tableCell(text: string): string {
	return text.replace(/\r?\n/gu, " ").replace(/\|/gu, "\\|");
}

function quoteLine(text: string): string {
	return text.replace(/\r?\n/gu, " ");
}

function statusLine(record: TeamProposalRecord): string {
	const blockers = record.unresolvedBlocking
		.map(finding => `${finding.id}：${finding.issue}；依据：${finding.evidence}`)
		.join("；");
	if (record.excludedFromOptions) {
		return `⛔ 尚不可采用 — ${record.exclusionReason ?? "不可作为最终选项"}${blockers ? `；未解决阻断问题：${blockers}` : ""}`;
	}
	if (record.unresolvedBlocking.length > 0) {
		const cap = record.blockedAfterRoundCap ? "（两轮修订后仍未解决）" : "";
		return `⛔ 尚不可采用 — 未解决阻断问题${cap}：${blockers}`;
	}
	if (record.blockedAfterRoundCap) {
		return "⛔ 尚不可采用 — 两轮修订后仍有阻断问题";
	}
	return "✅ 可作为选项";
}

/** §2.8 adoptability: offered as a final option, with no unresolved blocking finding and no round-cap block. */
function isAdoptable(record: TeamProposalRecord): boolean {
	return !record.excludedFromOptions && record.unresolvedBlocking.length === 0 && !record.blockedAfterRoundCap;
}

/** Whether the recommendation may stand: an existing, non-excluded, non-blocked proposal. */
function recommendationIsValid(synthesis: TeamSynthesisOutput, proposals: readonly TeamProposalRecord[]): boolean {
	const label = synthesis.recommendedProposal.trim();
	if (!label) return false;
	const record = proposals.find(candidate => candidate.label === label);
	if (!record) return false;
	return isAdoptable(record);
}

/**
 * A condition guards only its next adoption predicate, never a later claim.
 * Resolution conditions have no arbitrary length limit: the sentence/field
 * boundaries and the preceding predicate delimit their scope instead.
 */
// 条件分句后的“则／那么”同样连接下一处采用谓词，不扩大条件对后续推荐的作用域。
const CONDITIONAL_ADOPTION_PREFIX = new RegExp(
	[
		"(?:一旦|如果|若|只要|待|假如|倘若|仅在|只有在)[^。！？；;!?\\n]*(?:解决|修复|解除|满足|关闭|消除|证实|确认|复核通过)[^，,。！？；;!?\\n]*(?:[，,]|方案[A-Z]+|[A-Z]+方案)*(?:即|便|才|再|就|方|则|那么)?(?:可|可以|建议)?$",
		"(?:解决|修复|解除|满足|关闭|消除|证实|确认|复核通过)[^。！？；;!?\\n]*?(?:之后|以后|之时|后)(?:[，,]|方案[A-Z]+|[A-Z]+方案)*(?:即|便|才|再|就|方|则|那么)?(?:可|可以|建议)?$",
	].join("|"),
	"u",
);

/** A model-authored adoption claim must not override the tracked proposal status. */
function synthesisProseConflict(
	synthesis: TeamSynthesisOutput,
	proposals: readonly TeamProposalRecord[],
): string | undefined {
	const prose = [synthesis.reportMarkdown];
	// Recommendation prose is emitted only when the structured choice is valid.
	// Separate fields like paragraphs so a condition or label cannot guard a
	// different field's claim.
	if (recommendationIsValid(synthesis, proposals)) {
		prose.push(synthesis.recommendationReason, synthesis.recommendationPreconditions);
	}
	const body = prose.join("\n\n");
	if (normalizeHtmlEntitiesForTerminal(stripInlineMarkdown(body)).includes("【推荐】"))
		return "综合正文自行写入了【推荐】标记";
	// Keep commas and wrapped lines: a label and its predicate may straddle
	// either, as may an explicit adoption condition. Paragraphs isolate claims,
	// but Markdown subsections inherit their enclosing proposal's ownership.
	const statements: { text: string; scope: readonly TeamProposalRecord[] }[] = [];
	for (const field of prose) {
		// Fields are independent: report headings must not scope recommendation
		// reasons or preconditions. Use the renderer's lexer for heading levels.
		const headings: { depth: number; scope: readonly TeamProposalRecord[] }[] = [];
		let pending = "";
		const flushStatements = () => {
			// Strip Markdown before decoding, just as the renderer does: an
			// encoded delimiter is visible text, not new Markdown syntax.
			// Decode before sentence splitting so entity semicolons stay whole.
			for (const paragraph of pending.split(/\r?\n\s*\r?\n/u)) {
				const visible = normalizeHtmlEntitiesForTerminal(stripInlineMarkdown(paragraph));
				for (const text of visible.split(
					/(?:[。！？；;!?]|(?<![\p{L}\p{N}_/\\-])\.|\.(?![\p{L}\p{N}_/\\-])|但是|但|而|却)/u,
				)) {
					statements.push({ text, scope: headings.at(-1)?.scope ?? [] });
				}
			}
			pending = "";
		};
		for (const token of Lexer.lex(field)) {
			if (token.type === "heading") {
				flushStatements();
				while (headings.length > 0 && headings.at(-1)!.depth >= token.depth) headings.pop();
				const heading = normalizeHtmlEntitiesForTerminal(stripInlineMarkdown(token.text)).replace(/\s+/gu, "");
				const named = [...heading.matchAll(/方案([A-Z]+)|([A-Z]+)方案/gu)]
					.map(match => proposals.find(record => record.label === (match[1] ?? match[2])))
					.filter((record): record is TeamProposalRecord => record !== undefined);
				headings.push({ depth: token.depth, scope: named.length > 0 ? named : (headings.at(-1)?.scope ?? []) });
				statements.push({
					text: normalizeHtmlEntitiesForTerminal(stripInlineMarkdown(token.text)),
					scope: headings.at(-1)?.scope ?? [],
				});
				continue;
			}
			pending += token.raw;
		}
		flushStatements();
	}
	for (const { text: statement, scope } of statements) {
		// Compare visible prose, not Markdown delimiters: `方案 **A**` names
		// the same proposal as `方案 A` in the delivered report.
		const positiveClaims = statement
			.replace(/\s+/gu, "")
			// Remove only the negated predicate, not its clause: a later
			// affirmative endorsement must still be checked.
			.replace(
				/(?:不(?:再|予|能|应(?:当)?|宜|该|可(?:以)?|值得)?|并非|不是)(?:采用|作为(?:最终)?(?:选项|首选)|建议采用|推荐|首选)|(?:没有|无)(?:任何)?推荐(?:价值|必要|理由)/gu,
				"",
			);
		const mentions: { index: number; end: number; record: TeamProposalRecord }[] = [];
		for (const match of positiveClaims.matchAll(/方案([A-Z]+)|([A-Z]+)方案/gu)) {
			const record = proposals.find(candidate => candidate.label === (match[1] ?? match[2]));
			if (record) mentions.push({ index: match.index, end: match.index + match[0].length, record });
		}
		let previousClaimEnd = 0;
		for (const claim of positiveClaims.matchAll(/(?:可(?:以)?(?:采用|作为(?:最终)?选项)|建议采用|推荐|首选)/gu)) {
			const prefix = positiveClaims.slice(previousClaimEnd, claim.index);
			previousClaimEnd = claim.index + claim[0].length;
			if (CONDITIONAL_ADOPTION_PREFIX.test(prefix)) continue;
			// A standalone adoption claim does not name a proposal in the next
			// comma clause. Keep label-before-predicate claims across commas
			// ("方案 A，可以采用") and comparisons within a clause.
			let nearestIndex = -1;
			let nearestDistance = Infinity;
			for (const [index, mention] of mentions.entries()) {
				if (
					mention.index >= claim.index + claim[0].length &&
					/[，,]/u.test(positiveClaims.slice(claim.index + claim[0].length, mention.index))
				)
					continue;
				const distance = Math.max(mention.index - (claim.index + claim[0].length), claim.index - mention.end, 0);
				if (distance < nearestDistance) {
					nearestIndex = index;
					nearestDistance = distance;
				}
			}
			if (nearestIndex < 0) {
				// Comparison headings own ordered alternatives. An explicit
				// 前者/后者 identifies one alternative, not the whole group.
				const reference = /前者|后者/gu;
				const before = [...prefix.matchAll(reference)].at(-1)?.[0];
				const after = /^(前者|后者)/u.exec(positiveClaims.slice(previousClaimEnd))?.[1];
				const relative = after ?? before;
				const owners = scope.length === 2 && relative ? [relative === "前者" ? scope[0] : scope[1]] : scope;
				const blocked = owners.find(record => !isAdoptable(record));
				if (blocked) return `综合正文建议采用已标记为“尚不可采用”的方案 ${blocked.label}`;
				continue;
			}
			let first = nearestIndex;
			let last = nearestIndex;
			const conjunction = /^(?:和|与|及|或|以及|、|\/|&|\+)+$/u;
			while (first > 0 && conjunction.test(positiveClaims.slice(mentions[first - 1].end, mentions[first].index)))
				first--;
			while (
				last + 1 < mentions.length &&
				conjunction.test(positiveClaims.slice(mentions[last].end, mentions[last + 1].index))
			)
				last++;
			// In "方案 A 比方案 B 更值得推荐", B is the comparison
			// object, not the endorsed subject. Resolve an object (including a
			// coordinated group) back to its subject before checking status.
			if (
				first > 0 &&
				mentions[last].end <= claim.index &&
				/^(?:比|相比|比起)$/u.test(positiveClaims.slice(mentions[first - 1].end, mentions[first].index))
			) {
				last = first - 1;
				first = last;
				while (first > 0 && conjunction.test(positiveClaims.slice(mentions[first - 1].end, mentions[first].index)))
					first--;
			}
			for (let index = first; index <= last; index++) {
				const { record } = mentions[index];
				if (!isAdoptable(record)) {
					return `综合正文建议采用已标记为“尚不可采用”的方案 ${record.label}`;
				}
			}
		}
	}
	return undefined;
}

export function assembleTeamReport(args: AssembleReportArgs): AssembleReportResult | AssembleReportConflict {
	const { alignment, synthesis, proposals } = args;
	const conflict = synthesisProseConflict(synthesis, proposals);
	if (conflict) return { ok: false, error: conflict };
	const sections: string[] = [];

	const choiceAffecting = alignment.interpretationDifferences.filter(difference => difference.affectsChoice);
	if (choiceAffecting.length > 0) {
		const lines = choiceAffecting.map(
			difference =>
				`> - ${quoteLine(difference.ambiguity)}：${difference.interpretations.map(view => quoteLine(view.view)).join(" / ")}`,
		);
		sections.push(
			[
				"> ⚠️ **存在实质影响方案选择的需求理解差异——请先回答差异、带答案重跑 `/team`，不要在不同前提的方案间盲选：**",
				...lines,
			].join("\n"),
		);
	}

	sections.push(synthesis.reportMarkdown.trim());

	const statusRows = proposals.map(
		record =>
			`| ${proposalLabel(record)} | ${tableCell(statusLine(record))} | 提案${record.participant.isSessionModel ? "（会话模型）" : ""}；审查轮数 ${record.reviews.length}；修订轮数 ${record.roundsUsed} |`,
	);
	sections.push(
		[
			"### 方案状态（结构化追踪，机械生效）",
			"",
			"| 方案 | 状态 | 参与情况 |",
			"| --- | --- | --- |",
			...statusRows,
			"",
		].join("\n"),
	);

	if (args.participationNotes.length > 0) {
		sections.push(["### 参与完整性与证据缺口", "", ...args.participationNotes.map(note => `- ${note}`)].join("\n"));
	}

	let droppedRecommendation = false;
	const recommendedLabel = synthesis.recommendedProposal.trim();
	if (recommendationIsValid(synthesis, proposals)) {
		const preconditions = synthesis.recommendationPreconditions
			? `（前提：${synthesis.recommendationPreconditions}）`
			: "";
		sections.push(
			`**【推荐】${proposalLabel(proposals.find(p => p.label === recommendedLabel)!)}** — ${synthesis.recommendationReason}${preconditions}`,
		);
	} else if (recommendedLabel) {
		droppedRecommendation = true;
		sections.push(
			`> 结构化追踪否决了综合子调用对“${synthesis.recommendedProposal}”的推荐：该方案不存在、不可作为最终选项或仍有未解决阻断问题，故不给出推荐标记。`,
		);
	}

	sections.push(TEAM_CLOSING_CONTRACT);

	return {
		ok: true,
		markdown: [`## /team 多代理讨论结果（team-result）`, "", sections.join("\n\n")].join("\n"),
		droppedRecommendation,
	};
}

/** Failure message for runs that must not produce a half-finished conclusion. */
export function assembleTeamFailure(question: string, reason: string): string {
	return [
		"## /team 多代理讨论未完成（team-incomplete）",
		"",
		`本次流程未完成：${reason}`,
		"",
		"依据约定不输出半成品结论；请处理上述问题后重新发起 `/team`。",
		"",
		`> 原始问题：${question.slice(0, 500)}`,
	].join("\n");
}
